try {
    limit = limit ?? 25;
    let offset = 0;

    if (currentPage) {
        offset = (currentPage - 1) * limit;
    }

    const response = await this.currentContext.payrollAppApi[endpoint](
        {
            limit, offset
        },
        {
            headers: this.authCookies.setHeaders()
        }
    )

    if (response.status == 200) {
        return response.data[entity]
    } else {
        this.utils.toast(response.data.message, response.data.result);
        throw response;
    }

} catch (e) {
    console.error("Error getting data:", e);
}

// limit = limit || 25;

// const offset = currentPage ? (currentPage - 1) * limit : 0;

// return this.currentContext.payrollAppApi[endpoint](
//     { limit: limit, offset: offset },
//     { headers: this.authCookies.setHeaders() }
// )
//     .then((result) => result.data[entity])
//     .catch((reason) => {
//         this.utils.toast(reason.data.message, reason.data.result);
//         throw reason;
//     });

const processedData = this.processDataFields(data, {
    removeFields: options.removeFields,
    transformBooleansToYesNo: options.transformBooleans,
    replaceUserIdsWithNames: options.replaceUserIds,
    addCountryAndStateNames: options.addCountryStateNames,
    addUserRoles: options.addUserRoles,
    addPositionDetails: options.addPositionDetails,
    replaceCompanyIdsWithNames: options.replaceCompanyIds,
    replacePayScheduleIdsWithNames: options.replacePayScheduleIds,
    replaceTaxIdsWithNames: options.replaceTaxIds,
    replaceCurrencyIdsWithNames: options.replaceCurrencyIds,
    replaceEarningIdsWithNames: options.replaceEarningIds,
    replaceBenefitIdsWithNames: options.replaceBenefitIds,
    hideAccrualRelatedFields: options.hideAccrualFields
});

// Assign processed data to the specified ctrl property
if (options.ctrlDataName) {
    this.currentContext[options.ctrlDataName] = processedData;
}

// Handle column visibility and transformation if specified
if (options.ctrlColumnName && options.hideColumns) {
    this.currentContext[options.ctrlColumnName] = this.processDataFields(data, { hideColumns: true })[0];
}

// Map entities to labels and values if specified
if (options.mapToLabelValue && options.entityList && options.mapLabelKey && options.mapValueKey) {
    this.currentContext[options.mapToLabelValue] = mapEntitiesToLabelsAndValues(
        options.entityList,
        options.mapLabelKey,
        options.mapValueKey
    );
}

return processedData;

// Mapping Functions
function mapEntitiesToLabelsAndValues(entities, labelKeyOrKeys, valueKey) {
    return entities
        .filter(entity => {
            // Check if labelKeyOrKeys is an array (multiple keys) or a single string
            if (Array.isArray(labelKeyOrKeys)) {
                // Ensure all keys in labelKeyOrKeys have values in entity
                return entity && labelKeyOrKeys.every(key => entity[key]) && entity[valueKey];
            } else {
                // Single key: ensure it has a value in entity
                return entity && entity[labelKeyOrKeys] && entity[valueKey];
            }
        })
        .map(entity => ({
            label: Array.isArray(labelKeyOrKeys)
                ? labelKeyOrKeys.map(key => entity[key]).join(' ')  // Combine multiple keys
                : entity[labelKeyOrKeys],  // Use single key directly
            value: entity[valueKey]
        }));
}

return data.map(record => {
  let updatedRecord = { ...record };

  // Replace user IDs with names
  if (options.replaceUserIdsWithNames && this.currentContext.users) {
    const createdByUser = this.currentContext.users.find(user => user.Id == updatedRecord.CreatedBy);
    const updatedByUser = this.currentContext.users.find(user => user.Id == updatedRecord.UpdatedBy);

    // Update fields only if corresponding user is found; otherwise, keep the original ID
    updatedRecord = {
      ...updatedRecord,
      CreatedBy: createdByUser ? `${createdByUser.FirstName} ${createdByUser.LastName}` : updatedRecord.CreatedBy,
      UpdatedBy: updatedByUser ? `${updatedByUser.FirstName} ${updatedByUser.LastName}` : updatedRecord.UpdatedBy
    };

    if (updatedRecord?.Detail) {
      const detailCreatedByUser = this.currentContext.users.find(user => user.Id == updatedRecord.Detail.CreatedBy);
      const detailUpdatedByUser = this.currentContext.users.find(user => user.Id == updatedRecord.Detail.UpdatedBy);
      updatedRecord.Detail.CreatedBy = detailCreatedByUser ? `${detailCreatedByUser.FirstName} ${detailCreatedByUser.LastName}` : updatedRecord.Detail.CreatedBy;
      updatedRecord.Detail.UpdatedBy = detailUpdatedByUser ? `${detailUpdatedByUser.FirstName} ${detailUpdatedByUser.LastName}` : updatedRecord.Detail.UpdatedBy;
    }
  }

  // Replace company IDs with names
  if (options.replaceCompanyIdsWithNames && this.currentContext.companies) {
    const company = this.currentContext.companies.find(company => company.Id === updatedRecord.CompanyId);
    if (company) updatedRecord.Company = company.LegalName;
  }

  // Replace pay schedule IDs with names
  if (options.replacePayScheduleIdsWithNames && this.currentContext.paySchedules && !updatedRecord.OffCycle) {
    const paySchedule = this.currentContext.paySchedules
      .find(paySchedule => paySchedule.Id === (updatedRecord?.PayScheduleId ||
        this.currentContext.payPeriods
          .find(payPeriod => payPeriod.Id === updatedRecord.PayPeriodId)?.PayScheduleId));

    if (paySchedule) updatedRecord = {
      PaySchedule: paySchedule.DisplayName,
      ...Object.fromEntries(
        Object.entries(updatedRecord)
          .filter(([key]) =>
            !['CreatedDate', 'CreatedBy', 'UpdatedDate', 'UpdatedBy'].includes(key))),
      CreatedDate: updatedRecord.CreatedDate,
      CreatedBy: updatedRecord.CreatedBy,
      UpdatedDate: updatedRecord.UpdatedDate,
      UpdatedBy: updatedRecord.UpdatedBy
    }
  }

  if (options.replaceEarningIdsWithNames && this.currentContext.earnings) {
    const earning = this.currentContext.earnings.find(earning => earning.Id === updatedRecord.EarningId);
    if (earning) updatedRecord.Earning = earning.Name;
  }

  if (options.replaceBenefitIdsWithNames && this.currentContext.benefits) {
    const benefit = this.currentContext.benefits.find(benefit => benefit.Id === updatedRecord.BenefitId);
    if (benefit) updatedRecord.Benefit = benefit.Name;
  }

  // Add Position Details
  if (options.addPositionDetails && this.currentContext.positions && this.currentContext.workerPositions) {
    const workerPosition = this.currentContext.workerPositions.find(workerPosition => workerPosition.WorkerId === updatedRecord.Id);

    if (workerPosition) {
      const positionDetails = this.currentContext.positions.find(position => position.Id === workerPosition.PositionId);

      updatedRecord = {
        Department: positionDetails.Department,
        Title: positionDetails.Title,
        CustomAnnualRate: workerPosition.CustomAnnualRate,
        ...Object.fromEntries(
          Object.entries(updatedRecord).filter(([key]) =>
            !['CreatedDate', 'CreatedBy', 'UpdatedDate', 'UpdatedBy'].includes(key)
          )
        ),
        PositionId: positionDetails.Id,
        WorkerPositionId: workerPosition.Id,
        CreatedDate: updatedRecord.CreatedDate,
        CreatedBy: updatedRecord.CreatedBy,
        UpdatedDate: updatedRecord.UpdatedDate,
        UpdatedBy: updatedRecord.UpdatedBy,
      }
    }
  }

  // Replace tax IDs with names
  if (options.replaceTaxIdsWithNames && this.currentContext.taxes) {
    const tax = this.currentContext.taxes.find(tax => tax.Id === updatedRecord.TaxId);
    if (tax) updatedRecord = Object.entries(updatedRecord).reduce((acc, [key, value]) => {
      if (key === "TaxId") acc.Tax = tax.Name;
      acc[key] = value;
      return acc;
    }, {});
  }

  // Replace currency IDs with names
  if (options.replaceCurrencyIdsWithNames && this.currentContext.currencies) {
    const currency = this.currentContext.currencies.find(currency => currency.Id === updatedRecord.CurrencyId);
    if (currency) updatedRecord = Object.entries(updatedRecord).reduce((acc, [key, value]) => {
      if (key === "CurrencyId") acc.Currency = currency.CurrencyName;
      acc[key] = value;
      return acc;
    }, {});
  }

  // Add country and state names
  if (options.addCountryAndStateNames && this.currentContext.countries && this.currentContext.states) {
    const country = this.currentContext.countries.find(country => country.Id === updatedRecord.CountryId);
    const state = this.currentContext.states.find(state => state.Id === updatedRecord.StateId);
    if (country) updatedRecord = Object.entries(updatedRecord).reduce((acc, [key, value]) => {
      if (key === "CountryId") acc.Country = country.Name;
      if (state && key === "StateId") acc.State = state.Name;
      acc[key] = value;
      return acc;
    }, {});
  }

  // Add User Roles
  if (options.addUserRoles && this.currentContext.userRoles) {
    const isWorker = this.currentContext.userRoles.find(userRole => userRole.UserId === updatedRecord.Id && userRole.RoleId === 1) ? true : false;
    const isPayrollAdmin = this.currentContext.userRoles.find(userRole => userRole.UserId === updatedRecord.Id && userRole.RoleId === 2) ? true : false;

    updatedRecord = {
      ...Object.fromEntries(
        Object.entries(updatedRecord).filter(([key]) =>
          !['CreatedDate', 'CreatedBy', 'UpdatedDate', 'UpdatedBy'].includes(key)
        )
      ),
      IsWorker: isWorker,
      IsPayrollAdmin: isPayrollAdmin,
      CreatedDate: updatedRecord.CreatedDate,
      CreatedBy: updatedRecord.CreatedBy,
      UpdatedDate: updatedRecord.UpdatedDate,
      UpdatedBy: updatedRecord.UpdatedBy,
    };
  }

  // Transform boolean fields
  if (options.transformBooleansToYesNo === undefined || options.transformBooleansToYesNo) {
    updatedRecord = moveBooleansToEnd(updatedRecord);
    // updatedRecord = booleanToYesNo(updatedRecord);
  }

  // Remove specified fields
  if (options.removeFields) {
    options.removeFields.forEach(field => delete updatedRecord[field]);
  }

  // Hide columns and transform column names if specified
  // TODO: Pass the columns to be hidden as arguments instead of a fixed array
  if (options.hideColumns) {
    updatedRecord = Object.keys(updatedRecord)
      .filter(columnName => ![
        ...(window.location.hash === "#!/dashboard" ? [] : ["EffectiveFromDate", "EffectiveToDate"]),
        "Description", "Detail",
        "DayStartTime", "WorkingDays", "PayDateOnBD",
        "MonthFirstStartDay", "MonthFirstPayDay", "MonthSecondStartDay", "MonthSecondPayDay",
        "WeekStartDayName", "WeekPayDayName",
        "UnitsType", "AccrualRate", "AccrualRateUnit", "AccrualCycleDay", "AccrualCycleMonth", "CashDay", "CashMonth",
        "Id", "CountryId", "CompanyId", "PayScheduleId", "CalculationMethodId", "TaxCalculationMethodId", "EmployeeCalculationMethodId", "EmployerCalculationMethodId", "CurrencyId", "WorkerId", "TaxId", "AccrualId", "EarningId", "PayPeriodId",
        "CreatedDate", "CreatedBy", "UpdatedDate", "UpdatedBy", "Custom", "Deleted", "DeletedYesNo"
      ].includes(columnName)) // && typeof updatedRecord[columnName] !== "boolean")
      .map(columnName => {
        const originalColumn = columnName;

        // Simplify column names
        if (columnName.includes("Primary")) columnName = columnName.replace("Primary", "");
        if (columnName.includes("Contact")) columnName = columnName.replace("Contact", "");
        if (columnName.includes("Location")) columnName = columnName.replace("Location", "");

        if (typeof updatedRecord[originalColumn] === "boolean") return {
          name: columnName,
          hide: false,
          textAlign: "left",
          enableSorting: true,
          sortBy: "none",
          enableFiltering: false,
          enablePinning: false,
          type: "boolean",
          cellTemplate: "default",
          cellConditionalStyle: [],
          cellActions: [],
          classes: [],
          conditionalClasses: [],
          valueKey: originalColumn
        };

        return {
          name: columnName,
          hide: false,
          textAlign: "left",
          enableSorting: true,
          sortBy: "none",
          enableFiltering: false,
          enablePinning: false,
          type: "string",
          cellTemplate: "default",
          cellConditionalStyle: [],
          cellActions: [],
          classes: [],
          conditionalClasses: [],
          valueKey: originalColumn
        };
      });
  }

  if (options.hideAccrualRelatedFields && updatedRecord.AccrualMethod === "AWARDED") {
    updatedRecord = Object.keys(updatedRecord)
      .filter(key => !key.includes("Accrual") || key === "AccrualMethod")
      .reduce((obj, key) => {
        obj[key] = updatedRecord[key]
        return obj;
      }, {});
  }

  return updatedRecord;
});

function booleanToYesNo(obj) {
  for (const key in obj) {
    if (Object.hasOwnProperty.call(obj, key)) {
      if (typeof obj[key] === 'boolean') {
        obj[key.concat("YesNo")] = obj[key] ? 'YES' : 'NO';
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        booleanToYesNo(obj[key]);
      }
    }
  }
  return obj;
}

function moveBooleansToEnd(obj) {
  const nonBooleanProps = {};
  const booleanProps = {};
  const auditProps = {};
  const auditKeys = ["CreatedDate", "CreatedBy", "UpdatedDate", "UpdatedBy"];

  for (const key in obj) {
    if (Object.hasOwnProperty.call(obj, key)) {
      if (auditKeys.includes(key)) {
        auditProps[key] = obj[key];
      } else if (typeof obj[key] === 'boolean') {
        booleanProps[key] = obj[key];
      } else {
        nonBooleanProps[key] = obj[key];
      }
    }
  }

  return { ...nonBooleanProps, ...booleanProps, ...auditProps };
}
